#!/usr/bin/env python3
"""PHASE L — catalog pastes 1-4 (400 entries, master index to 500).

- Cross-checks all 400 entries against the manifest. 14 entries file as
  full canon records into 15 existing covering databases (oral-histories,
  scientific-instruments, algorithms, anatomy, math proofs, volcanoes,
  dream records, cryptocurrency, sign language, cartography, pharma-drugs,
  terraforming, space-elevator, antimatter).
- Builds 70 new databases grouped by the pastes' domain groups: 30
  public+signature pairs for pastes 1-3 (public = fact-checked real
  records, src=public-harvest; signature = his original catalog designs,
  src=signature, " (Signature Edition)" titles) and 10 signature-only
  databases for paste 4 (ultra-advanced/cosmic, Signature-original,
  clearly labeled).
- Whole-system dedupe via code/dedupe_gate.py. Scholarly tone; no weapons
  content; no operational tradecraft; no website references; no Facebook.

Tuple: (key, cat, title, desc, points, req, standards, citations, demo_kind, target)
target None => seed into the new paste-domain catalog named by cat.
PUB: key -> (title, desc, points, req, standards, citations, demo_kind) for the
fact-checked public counterpart of a new-DB entry (pastes 1-3 only).
"""

